import React from 'react';
import { kbdStyleKeys } from '../lib/core';
import styles from './kbd.module.scss';

export interface KbdProps extends React.HTMLAttributes<HTMLElement> {}

const Kbd = React.forwardRef<HTMLElement, KbdProps>(({ className = '', children, ...props }, ref) => {
	return (
		<kbd ref={ref} className={`${styles[kbdStyleKeys.base]} ${className}`} {...props}>
			{children}
		</kbd>
	);
});
Kbd.displayName = 'Kbd';

export interface KbdGroupProps extends React.HTMLAttributes<HTMLElement> {}

const KbdGroup = React.forwardRef<HTMLElement, KbdGroupProps>(({ className = '', children, ...props }, ref) => {
	return (
		<kbd ref={ref} className={`${styles[kbdStyleKeys.group]} ${className}`} {...props}>
			{children}
		</kbd>
	);
});
KbdGroup.displayName = 'KbdGroup';

export { Kbd, KbdGroup };
export default Kbd;

@use '../../../styles/variables/colors' as *;

.kbd {
	pointer-events: none;
	display: inline-flex;
	height: 1.25rem;
	width: fit-content;
	min-width: 1.25rem;
	align-items: center;
	justify-content: center;
	gap: $spacing-1;
	border-radius: var(--tile-kbd-radius, $radius-sm);
	background-color: var(--tile-kbd-background, $muted);
	box-shadow: var(--tile-kbd-shadow, none);
	padding: 0 $spacing-1;
	font-family: $font-sans;
	font-size: $text-xs;
	font-weight: $font-medium;
	color: var(--tile-kbd-color, $muted-foreground);
	user-select: none;

	svg {
		width: 0.75rem;
		height: 0.75rem;
	}
}

.kbdGroup {
	display: inline-flex;
	align-items: center;
	gap: $spacing-1;
}
